using System.Collections.Generic; using UnityEngine;
namespace Reflectable { public sealed class BlockGrid { public const int Columns=7, Rows=7; readonly Dictionary<Vector2Int,BlockController> cells=new(); public bool Add(BlockController b){var k=new Vector2Int(b.GridColumn,b.GridRow);if(cells.ContainsKey(k))return false;cells.Add(k,b);return true;} public void Remove(BlockController b){cells.Remove(new Vector2Int(b.GridColumn,b.GridRow));} public IEnumerable<BlockController> Neighbours(BlockController b){for(int y=-1;y<=1;y++)for(int x=-1;x<=1;x++)if(cells.TryGetValue(new Vector2Int(b.GridColumn+x,b.GridRow+y),out var n)&&n!=b)yield return n;} } }
